import base from './graph-ui/vite.config.ts';
import { defineConfig, mergeConfig } from 'vite';
const origin = 'http://127.0.0.1:9749';
const allowedHosts = new Set(['127.0.0.1:9751', 'localhost:9751']);
const allowedOrigins = new Set(['http://127.0.0.1:9751', 'http://localhost:9751']);
function allowed(req) {
    return allowedHosts.has(req.headers.host ?? '') &&
        (req.headers.origin === undefined || allowedOrigins.has(req.headers.origin));
}
function enforce(req, res, next) {
    if (!allowed(req)) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end('{"error":"forbidden preview host or origin"}');
        return;
    }
    next();
}
const proxy = () => ({
    target: origin, changeOrigin: true, headers: { Origin: origin },
    bypass(req, res) {
        if (!allowed(req)) {
            res.writeHead(403, { 'Content-Type': 'application/json' });
            res.end('{"error":"forbidden preview host or origin"}');
            return false;
        }
        return undefined;
    },
});
export default defineConfig(mergeConfig(base, {
    root: new URL('./graph-ui/', import.meta.url).pathname,
    cacheDir: new URL('./vite-cache/', import.meta.url).pathname,
    plugins: [{ name: 'comparison-loopback-guard', configureServer(server) {
        server.middlewares.use(enforce);
    }, configurePreviewServer(server) { server.middlewares.use(enforce); } }],
    server: { host: '127.0.0.1', port: 9751, strictPort: true,
        allowedHosts: ['127.0.0.1', 'localhost'],
        cors: { origin: [...allowedOrigins] },
        proxy: { '/rpc': proxy(), '/api': proxy() } },
    preview: { host: '127.0.0.1', port: 9751, strictPort: true,
        allowedHosts: ['127.0.0.1', 'localhost'],
        cors: { origin: [...allowedOrigins] },
        proxy: { '/rpc': proxy(), '/api': proxy() } },
}));
